package com.jiugeng.erp.supplier;
import static com.jiugeng.erp.supplier.SupplierTypes.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository class SupplierRepository{
void lockMaterial(String id){jdbc.sql("SELECT id FROM auxiliary_material WHERE id=:id FOR UPDATE").param("id",id).query(String.class).optional().orElseThrow(()->new SupplierException(404,"MATERIAL_NOT_FOUND","辅料不存在"));}
void touchMaterial(String id){jdbc.sql("UPDATE auxiliary_material SET version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id").param("id",id).update();}
private final JdbcClient jdbc;SupplierRepository(JdbcClient jdbc){this.jdbc=jdbc;}
private String searchWhere(){return " WHERE (:term='' OR LOWER(name) LIKE :like ESCAPE '!' OR LOWER(COALESCE(contact_person,'')) LIKE :like ESCAPE '!' OR LOWER(COALESCE(phone,'')) LIKE :like ESCAPE '!' OR LOWER(COALESCE(wechat_id,'')) LIKE :like ESCAPE '!') AND (:status IS NULL OR status=:status) AND (:category IS NULL OR categories LIKE :categoryLike)";}
private org.springframework.jdbc.core.simple.JdbcClient.StatementSpec search(String sql,String q,Status status,Category category){String term=q==null?"":q.trim().toLowerCase(Locale.ROOT);String escaped=term.replace("!","!!").replace("%","!%").replace("_","!_");return jdbc.sql(sql).param("term",term).param("like","%"+escaped+"%").param("status",status==null?null:status.name()).param("category",category==null?null:category.name()).param("categoryLike",category==null?"%":"%"+category.name()+"%");}
List<View> list(String q,Status status,Category category,int page,int size){return search("SELECT * FROM supplier"+searchWhere()+" ORDER BY name,id LIMIT :size OFFSET :offset",q,status,category).param("size",size).param("offset",(long)page*size).query(this::view).list();}
long count(String q,Status status,Category category){return search("SELECT COUNT(*) FROM supplier"+searchWhere(),q,status,category).query(Long.class).single();}
void lock(String id){jdbc.sql("SELECT id FROM supplier WHERE id=:id FOR UPDATE").param("id",id).query(String.class).optional().orElseThrow(()->new SupplierException(404,"SUPPLIER_NOT_FOUND","供应商不存在"));}
Optional<View> find(String id){return jdbc.sql("SELECT * FROM supplier WHERE id=:id").param("id",id).query(this::view).optional();}
void insert(String id,Input i,String actor){jdbc.sql("INSERT INTO supplier(id,name,contact_person,phone,wechat_id,source_url,qr_image_url,qr_image_asset_id,remark,status,categories,created_by,updated_by) VALUES(:id,:name,:contact,:phone,:wechat,:url,:qrUrl,:qr,:remark,:status,:categories,:actor,:actor)").param("id",id).param("name",i.name()).param("contact",i.contactPerson()).param("phone",i.phone()).param("wechat",i.wechatId()).param("url",i.sourceUrl()).param("qrUrl",i.qrImageUrl()).param("qr",i.qrImageId()).param("remark",i.remark()).param("status",i.status().name()).param("categories",i.categories().stream().map(Enum::name).sorted().collect(java.util.stream.Collectors.joining(","))).param("actor",actor).update();}
int update(String id,Input i,String actor,long version){return jdbc.sql("UPDATE supplier SET name=:name,contact_person=:contact,phone=:phone,wechat_id=:wechat,source_url=:url,qr_image_url=:qrUrl,qr_image_asset_id=:qr,remark=:remark,status=:status,categories=:categories,version=version+1,updated_by=:actor,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version").param("id",id).param("name",i.name()).param("contact",i.contactPerson()).param("phone",i.phone()).param("wechat",i.wechatId()).param("url",i.sourceUrl()).param("qrUrl",i.qrImageUrl()).param("qr",i.qrImageId()).param("remark",i.remark()).param("status",i.status().name()).param("categories",i.categories().stream().map(Enum::name).sorted().collect(java.util.stream.Collectors.joining(","))).param("actor",actor).param("version",version).update();}
int delete(String id,long version){return jdbc.sql("DELETE FROM supplier WHERE id=:id AND version=:version").param("id",id).param("version",version).update();}
List<Dependency> dependencies(String id){return jdbc.sql("""
 SELECT 'PRODUCT' kind,v.id,p.id parent_id,v.sku_code code,v.variant_name label,CASE WHEN p.deleted_at IS NOT NULL OR v.deleted_at IS NOT NULL THEN 1 ELSE 0 END archived
 FROM product_variant_supplier l JOIN product_variant v ON v.id=l.variant_id JOIN product p ON p.id=v.product_id WHERE l.supplier_id=:id
 UNION ALL
 SELECT 'MATERIAL',m.id,m.id,m.material_code,m.name,0 FROM auxiliary_material_supplier l JOIN auxiliary_material m ON m.id=l.auxiliary_material_id WHERE l.supplier_id=:id
 UNION ALL
 SELECT 'PURCHASE',p.id,p.id,p.order_no,p.status,0 FROM purchase_order p WHERE p.supplier_id=:id
 ORDER BY kind,code,id
 """).param("id",id).query((r,n)->new Dependency(r.getString("kind"),r.getString("id"),r.getString("parent_id"),r.getString("code"),r.getString("label"),true,r.getBoolean("archived"))).list();}
int unlinkArchivedVariant(String supplier,String variant){return jdbc.sql("""
 DELETE FROM product_variant_supplier WHERE supplier_id=:supplier AND variant_id=:variant
 AND EXISTS (SELECT 1 FROM product_variant v JOIN product p ON p.id=v.product_id WHERE v.id=:variant AND (p.deleted_at IS NOT NULL OR v.deleted_at IS NOT NULL))
 """).param("supplier",supplier).param("variant",variant).update();}
boolean active(String id){return jdbc.sql("SELECT COUNT(*) FROM supplier WHERE id=:id AND status='ACTIVE'").param("id",id).query(Integer.class).single()>0;}
List<SupplierAssignmentGateway.LinkedSupplier> materialAssignments(String id){return jdbc.sql("SELECT s.id,s.name,s.status,s.categories,s.contact_person,s.phone,s.wechat_id,s.source_url,r.purchase_url,r.remark,r.primary_slot FROM auxiliary_material_supplier r JOIN supplier s ON s.id=r.supplier_id WHERE r.auxiliary_material_id=:id ORDER BY CASE WHEN r.primary_slot='PRIMARY' THEN 0 ELSE 1 END,s.name,s.id").param("id",id).query((r,n)->new SupplierAssignmentGateway.LinkedSupplier(r.getString("id"),r.getString("name"),r.getString("status"),Arrays.asList(r.getString("categories").split(",")).contains("MATERIAL"),r.getString("contact_person"),r.getString("phone"),r.getString("wechat_id"),r.getString("source_url"),r.getString("purchase_url"),r.getString("remark"),"PRIMARY".equals(r.getString("primary_slot")))).list();}
List<LinkView> links(String table,String ownerColumn,String ownerId){String sql="SELECT r.id,r."+ownerColumn+" owner_id,r.supplier_id,s.name,s.status,r.purchase_url,r.remark,r.primary_slot,r.updated_at FROM "+table+" r JOIN supplier s ON s.id=r.supplier_id WHERE r."+ownerColumn+"=:owner ORDER BY CASE WHEN r.primary_slot='PRIMARY' THEN 0 ELSE 1 END,s.name";return jdbc.sql(sql).param("owner",ownerId).query(this::link).list();}
void deleteLinks(String table,String ownerColumn,String ownerId){jdbc.sql("DELETE FROM "+table+" WHERE "+ownerColumn+"=:owner").param("owner",ownerId).update();}
void insertLink(String table,String ownerColumn,String ownerId,LinkInput i,String actor){jdbc.sql("INSERT INTO "+table+"(id,"+ownerColumn+",supplier_id,purchase_url,remark,primary_slot,created_by,updated_by) VALUES(:id,:owner,:supplier,:url,:remark,:primary,:actor,:actor)").param("id",UUID.randomUUID().toString()).param("owner",ownerId).param("supplier",i.supplierId()).param("url",i.purchaseUrl()).param("remark",i.remark()).param("primary",i.primary()?"PRIMARY":null).param("actor",actor).update();}
private View view(ResultSet r,int n)throws SQLException{return new View(r.getString("id"),r.getString("name"),r.getString("contact_person"),r.getString("phone"),r.getString("wechat_id"),r.getString("source_url"),r.getString("qr_image_url"),r.getString("qr_image_asset_id"),r.getString("remark"),Status.valueOf(r.getString("status")),r.getLong("version"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant(),Arrays.stream(r.getString("categories").split(",")).filter(v->!v.isBlank()).map(Category::valueOf).toList());}
private LinkView link(ResultSet r,int n)throws SQLException{return new LinkView(r.getString("id"),r.getString("owner_id"),r.getString("supplier_id"),r.getString("name"),Status.valueOf(r.getString("status")),r.getString("purchase_url"),r.getString("remark"),"PRIMARY".equals(r.getString("primary_slot")),r.getTimestamp("updated_at").toInstant());}
}
